INSERT_SQL = text("""
INSERT INTO products
(sku_no, continent, country, name, process, variety, flavor, rating, strategy,
 batch_hint, cost_range_raw, cost_ntd_100g_raw, retail_ntd_100g_raw, margin_pct_raw,
 notes, season, importer, shelf_life_months, is_active)
VALUES (:sku_no, :continent, :country, :name, :process, :variety, :flavor, :rating, :strategy,
 :batch_hint, :cost_range_raw, :cost_ntd_100g_raw, :retail_ntd_100g_raw, :margin_pct_raw,
 :notes, :season, :importer, :shelf_life_months, :is_active)
""")

DELETE_SQL = text("DELETE FROM products WHERE sku_no = :sku_no")

COLUMNS = ["sku_no","continent","country","name","process","variety","flavor","rating","strategy",
           "batch_hint","cost_range_raw","cost_ntd_100g_raw","retail_ntd_100g_raw","margin_pct_raw",
           "notes","season","importer","shelf_life_months","is_active"]


def seed():
    """匯入100 SKU商品主檔。採用「先刪除、再新增」方式達成upsert效果，
    同時相容SQLite與PostgreSQL兩種資料庫方言，避免使用資料庫專屬語法。"""
    init_db()
    with get_conn() as conn:
        for row in PRODUCTS:
            params = dict(zip(COLUMNS, row))
            conn.execute(DELETE_SQL, {"sku_no": params["sku_no"]})
            conn.execute(INSERT_SQL, params)
    print(f"已匯入 {len(PRODUCTS)} 筆SKU商品主檔至資料庫")


if __name__ == "__main__":
    seed()
